import express from 'express';

import createOpenpanelMiddleware from '@openpanel/express';

const app = express();

app.use(
  createOpenpanelMiddleware({
    apiUrl: 'https://api.privytics.com',
    clientId: 'YOUR_CLIENT_ID',
    clientSecret: 'YOUR_CLIENT_SECRET',
    // trackRequest(url) {
    //   return url.includes('/v1')
    // },
    // getProfileId(req) {
    //   return req.user.id
    // }
  })
);

app.listen(3000);

app.get('/sign-up', (req, res) => {
  // track sign up events
  req.op.track('sign-up', {
    email: req.body.email,
  });
  res.send('Hello World');
});

app.post('/login', async (req, res) => {
  const user = await loginUser(req.body);

  // Identify the user
  req.op.identify({ profileId: user.id, email: user.email });

  // Create/update the group entity
  req.op.upsertGroup({
    id: user.organizationId,
    type: 'company',
    name: user.organizationName,
    properties: { plan: user.plan },
  });

  // Assign the user to the group
  req.op.setGroup(user.organizationId);

  res.json({ ok: true });
});

faq.a:
The middleware adds `op` to the request object at runtime, so TypeScript needs a declaration to know about it. Add this to a `.d.ts` file or any module in your project:

```ts
import { OpenPanel } from '@openpanel/express';

declare global {
  namespace Express {
    export interface Request {
      op: OpenPanel;
    }
  }
}
```
